+        res = await this._request('/live-audio/sessions/', {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({
+            videoId: this.videoId,
+            sceneId: this.sceneId,
+            mime: this.mime,
+            recorderSessionId: this.recorderSessionId,
+          }),
